#' Build a combined spatial report for a species
#'
#' `sacha_spatial_report()` prints the geographic areas documented by
#' Catalogue of Life, followed by the GBIF occurrence map generated by
#' [gbif_map_crop_md()]. It uses the same species name for both sections and
#' preserves the output and error handling of those functions.
#'
#' Supply `species`, `language`, and any map argument directly through `...`:
#' `kml`, `crop_area`, `crop_box`, `limit`, `mode`, `save_occurrences`,
#' `export_image`, `directory`, `colour`, `dpi`, `ppp`, `overwrite`,
#' `distribution`, `fig_width`, `fig_height`, `source`, and `local_export`.
#' Alternatively, set shared argument defaults beforehand with
#' [sacha_arg_configure()]. An argument supplied in the function call takes
#' precedence over its configured default. The locations text uses
#' `language`; the map uses the active language in the spatial configuration.
#' Use [sacha_configure()] to set module defaults.
#'
#' @param species A binomial scientific name in the form `"Genus species"`.
#' @param ... Arguments forwarded to [gbif_map_crop_md()]: `kml`, `crop_area`,
#'   `crop_box`, `limit`, `mode`, `save_occurrences`, `export_image`,
#'   `directory`, `colour`, `dpi`, `ppp`, `overwrite`, `distribution`,
#'   `fig_width`, `fig_height`, `source`, and `local_export`. Their accepted
#'   values and defaults are documented in that function.
#' @param language Optional language for the Catalogue of Life locations text.
#'   Accepts `"es"`, `"en"`, or another language code configured by the
#'   package. `NULL` uses the active spatial language.
#' @return In a rendered document, returns the combined Markdown output. In an
#'   interactive session, returns the same map result as [gbif_map_crop_md()]
#'   after printing the locations text.
#' @examples
#' \dontrun{
#' species <- "Genus species"
#' boundary_file <- "region.kml"
#'
#' sacha_spatial_report(
#'   species, language = "en", kml = boundary_file,
#'   source = "gbif", export_image = TRUE
#' )
#'
#' sacha_arg_configure(
#'   species = species, language = "en", kml = boundary_file,
#'   source = "gbif", export_image = TRUE
#' )
#' sacha_spatial_report()
#' sacha_clear_cache()
#' }
#' @export
sacha_spatial_report <- function(species, ..., language = NULL) {
  .sacha_apply_arg_defaults(environment(), match.call(expand.dots = FALSE), names(formals(sys.function())))
  location_output <- paste(
    utils::capture.output(locations_md(species = species, language = language)),
    collapse = "\n"
  )
  map_arguments <- .sacha_merge_arg_defaults(
    list(...),
    setdiff(names(formals(gbif_map_crop_md)), c("species", "..."))
  )
  map_output <- do.call(
    gbif_map_crop_md,
    c(list(species = species), map_arguments)
  )

  if (inherits(map_output, "knit_asis")) {
    map_markdown <- paste(as.character(map_output), collapse = "\n")
    return(knitr::asis_output(
      paste(location_output, map_markdown, sep = "\n\n"),
      meta = attr(map_output, "knit_meta")
    ))
  }

  cat(location_output, "\n", sep = "")
  map_output
}

#' Compile taxonomic information into one Markdown report
#'
#' `sacha_clb_report()` combines the package accessors into a single
#' Markdown report, in this order: accepted scientific name and authorship,
#' first publication, indexed identifiers, common names, taxonomic
#' classification, synonyms and combinations, documented geographic
#' locations, and bibliographic references. It delegates each section to
#' the corresponding `_md` accessor so that the individual formatting and
#' source-handling rules remain in effect.
#'
#' Supply `species`, `language`, `rank`, `save_bib`, and `bib_dir` directly,
#' or set shared argument defaults beforehand with [sacha_arg_configure()].
#' Values supplied to `sacha_clb_report()` take precedence over configured
#' defaults.
#'
#' @param species A binomial scientific name in the form `"Genus species"`.
#' @param language Optional language for localized labels. Accepts `"es"`,
#'   `"en"`, or another language code configured by the package. `NULL` uses
#'   the active language configuration.
#' @param rank Optional argument forwarded to [classification_md()]; see its
#'   help page for accepted values and effects.
#' @param save_bib Argument forwarded to [references_sp_md()]; see its help
#'   page for its effect.
#' @param bib_dir Argument forwarded to [references_sp_md()]; see its help
#'   page for its effect.
#' @return Invisibly returns the combined Markdown string, which is also
#'   written to the console for insertion into a rendered document.
#' @examples
#' \dontrun{
#' species <- "Genus species"
#' sacha_clb_report(
#'   species, language = "en", rank = "family",
#'   save_bib = FALSE, bib_dir = "bibliography"
#' )
#'
#' sacha_arg_configure(
#'   species = species, language = "en", rank = "family",
#'   save_bib = FALSE, bib_dir = "bibliography"
#' )
#' sacha_clb_report()
#' sacha_clear_cache()
#' }
#' @export
sacha_clb_report <- function(species,
                             language = NULL,
                             rank = NULL,
                             save_bib = FALSE,
                             bib_dir = ".") {
  .sacha_apply_arg_defaults(environment(), match.call(expand.dots = FALSE), names(formals(sys.function())))
  sections <- list(
    function() sc_full_name_md(species),
    function() first_publicacion_md(species, language = language),
    function() indexations_md(species, language = language),
    function() common_names_md(species, language = language),
    function() classification_md(species, rank = rank, language = language),
    function() syn_and_comb_md(species, language = language),
    function() locations_md(species, language = language),
    function() references_sp_md(
      species, language = language, save_bib = save_bib, bib_dir = bib_dir
    )
  )
  rendered_sections <- vapply(sections, function(section) {
    paste(utils::capture.output(section()), collapse = "\n")
  }, character(1))
  rendered_sections <- rendered_sections[nzchar(trimws(rendered_sections))]
  markdown <- paste(rendered_sections, collapse = "\n\n")
  if (nzchar(markdown)) cat(markdown, "\n", sep = "")
  invisible(markdown)
}

#' Compile a complete species report
#'
#' `sacha_report()` combines taxonomic information, licensed iNaturalist
#' photographs, indexed identifiers, geographic locations, a GBIF map, and
#' bibliographic references in a single Markdown report. Sections are
#' produced in this order: accepted scientific name and authorship, first
#' publication, iNaturalist images, indexed identifiers, common names,
#' taxonomic classification, synonyms and combinations, documented
#' geographic locations, the cropped GBIF map, and bibliographic references.
#'
#' The default `source = "local"` uses locally available iNaturalist image
#' records and GBIF occurrence data. Before using this default, the relevant
#' local records must have been prepared with the package's save functions,
#' and the crop map must have a configured boundary or a previously saved
#' crop. `source` controls only the iNaturalist image and GBIF map sections.
#' ChecklistBank-backed taxonomic sections retain their configured web
#' behavior in either mode; the package does not yet read their records from a
#' local ColDP archive. The ChecklistBank adapter may also query GBIF and
#' iNaturalist to resolve taxon identifiers for indexation links. Thus, this
#' report is not fully offline even when `source = "local"`. The
#' `save_images`, `save_occurrences`, `export_comp`, and `export_image`
#' options can be forwarded to create local outputs while the report is
#' generated.
#'
#' Online requests are subject to the policies and availability of the
#' respective services. Prefer local data for repeated rendering, request
#' only the records needed, and avoid repeated refreshes or parallel report
#' builds against the same services. Image downloads also consume bandwidth;
#' iNaturalist publishes media-volume and request-rate recommendations in
#' its [API practices](https://www.inaturalist.org/pages/api+recommended+practices).
#' These safeguards cannot account for downloads initiated by other
#' processes or users on the same network.
#'
#' Values may be passed directly to `sacha_report()` through `species`,
#' `source`, `language`, and the names documented under `...`. Alternatively,
#' shared arguments can be set beforehand with [sacha_arg_configure()];
#' values supplied directly to `sacha_report()` take precedence.
#'
#' @param species A scientific name in the form `"Genus species"`.
#' @param source Data source for the iNaturalist image and GBIF map sections.
#'   `"local"` (default) uses previously saved image and occurrence records;
#'   `"web"` queries iNaturalist for images and GBIF for map occurrences.
#'   ChecklistBank-backed sections keep their configured web behavior in
#'   either mode, including any GBIF or iNaturalist lookups used to resolve
#'   indexation links.
#' @param language Optional language code forwarded to accessors that support
#'   localized output. `NULL` follows each module's active language setting.
#' @param ... Named arguments forwarded to the relevant underlying functions.
#'   Supported names are `user_id`, `number_observations`, `observation_id`,
#'   `image_size`, `verify_local`, `images_directory`, `quality_grade`,
#'   `place_id`, `catalogue_dataset`, `observer_name`, `save_images`,
#'   `export_comp`, `refresh`, `ncol`, `word_subfigure_width`,
#'   `latex_subfigure_width`, `identifier`, `rank`, `save_bib`, `bib_dir`,
#'   `kml`, `crop_area`, `crop_box`, `limit`, `mode`, `save_occurrences`,
#'   `export_image`, `directory`, `colour`, `dpi`, `ppp`, `overwrite`,
#'   `distribution`, `fig_width`, `fig_height`, and `local_export`. Their
#'   choices, defaults, and effects are documented by the corresponding
#'   accessors [inat_images_md()], [indexations_md()],
#'   [classification_md()], [references_sp_md()], and [gbif_map_crop_md()].
#'   The top-level `source` argument controls the source for both the image
#'   and map sections and must not be repeated in `...`.
#' @return In a rendered document, returns one Markdown object containing
#'   the combined sections and any figure metadata. In an interactive
#'   session, writes the Markdown sections to the console and returns the map
#'   result invisibly.
#' @examples
#' \dontrun{
#' sacha_report(species)
#' }
#' @export
sacha_report <- function(species,
                         source = c("local", "web"),
                         language = NULL,
                         ...) {
  .sacha_apply_arg_defaults(environment(), match.call(expand.dots = FALSE), names(formals(sys.function())))
  source <- match.arg(source)
  supported <- c(
    "user_id", "number_observations", "observation_id", "image_size",
    "verify_local", "images_directory", "quality_grade", "place_id",
    "catalogue_dataset", "observer_name", "save_images", "export_comp",
    "refresh", "ncol", "word_subfigure_width", "latex_subfigure_width",
    "identifier", "rank", "save_bib", "bib_dir", "kml", "crop_area",
    "crop_box", "limit", "mode", "save_occurrences", "export_image",
    "directory", "colour", "dpi", "ppp", "overwrite", "distribution",
    "fig_width", "fig_height", "local_export"
  )
  supplied <- .sacha_merge_arg_defaults(list(...), supported)
  if (length(supplied) && (is.null(names(supplied)) || any(!nzchar(names(supplied))))) {
    stop("All arguments in `...` must be named.", call. = FALSE)
  }
  unknown <- setdiff(names(supplied), supported)
  if (length(unknown)) {
    stop(
      "Unsupported argument(s) in `...`: ", paste(unknown, collapse = ", "),
      ". See the `...` documentation for supported arguments.",
      call. = FALSE
    )
  }
  if (anyDuplicated(names(supplied))) {
    stop("Arguments in `...` must not be supplied more than once.", call. = FALSE)
  }

  take <- function(keys) supplied[intersect(keys, names(supplied))]
  inat_keys <- c(
    "user_id", "number_observations", "observation_id", "image_size",
    "verify_local", "images_directory", "quality_grade", "place_id",
    "catalogue_dataset", "observer_name", "save_images", "export_comp",
    "refresh", "ncol", "word_subfigure_width", "latex_subfigure_width"
  )
  map_keys <- c(
    "kml", "crop_area", "crop_box", "limit", "mode", "save_occurrences",
    "export_image", "directory", "colour", "dpi", "ppp", "overwrite",
    "distribution", "fig_width", "fig_height", "local_export"
  )
  image_args <- c(
    list(species = species),
    if (!is.null(language)) list(language = language),
    take(inat_keys),
    list(source = source)
  )
  image_output <- paste(
    utils::capture.output(do.call(inat_images_md, image_args)),
    collapse = "\n"
  )

  section_args <- function(keys) {
    args <- list(species = species)
    if (!is.null(language)) args$language <- language
    c(args, take(keys))
  }
  capture_section <- function(fun, args) {
    paste(utils::capture.output(do.call(fun, args)), collapse = "\n")
  }

  text_sections <- c(
    capture_section(sc_full_name_md, list(species = species)),
    capture_section(first_publicacion_md, section_args(character())),
    image_output,
    capture_section(indexations_md, section_args("identifier")),
    capture_section(common_names_md, section_args(character())),
    capture_section(classification_md, section_args("rank")),
    capture_section(syn_and_comb_md, section_args(character())),
    capture_section(locations_md, section_args(character()))
  )

  map_source <- if (identical(source, "web")) "gbif" else "local"
  map_args <- c(
    list(species = species),
    take(map_keys),
    list(source = map_source)
  )
  map_capture <- character()
  map_output <- NULL
  map_capture <- utils::capture.output(map_output <- do.call(gbif_map_crop_md, map_args))
  map_metadata <- list()
  if (inherits(map_output, "knit_asis")) {
    map_markdown <- paste(as.character(map_output), collapse = "\n")
    map_metadata <- attr(map_output, "knit_meta")
  } else {
    map_markdown <- paste(map_capture, collapse = "\n")
  }

  references_args <- c(
    list(species = species),
    if (!is.null(language)) list(language = language),
    take(c("save_bib", "bib_dir"))
  )
  references_output <- capture_section(references_sp_md, references_args)
  report_sections <- c(text_sections, map_markdown, references_output)
  report_sections <- report_sections[nzchar(trimws(report_sections))]
  markdown <- paste(report_sections, collapse = "\n\n")

  if (inherits(map_output, "knit_asis")) {
    return(knitr::asis_output(markdown, meta = map_metadata))
  }

  before_map <- c(text_sections, map_markdown)
  before_map <- before_map[nzchar(trimws(before_map))]
  if (length(before_map)) cat(paste(before_map, collapse = "\n\n"), "\n", sep = "")
  if (!is.null(map_output)) print(map_output)
  if (nzchar(trimws(references_output))) cat(references_output, "\n", sep = "")
  invisible(map_output)
}
